using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class AccountingImportRuleTests
{
    private static readonly DateTimeOffset Now=new(2026,10,24,18,0,0,TimeSpan.Zero);
    private static AccountingImportInput Input()=>new(1,"Company-A","Warehouse-01","physical","IRR",Now,false,[new("0001-Ab",null,"گوشی نمونه","EA","2","9007199254740993")]);
    [Fact] public void OpaqueIdentifiersAndAboveJsPrecisionPriceArePreserved(){var x=Input();AccountingImportRules.Validate(x,Now,false);var v=AccountingImportRules.Inspect(x.Rows[0].QuantityRaw,x.Rows[0].PriceRaw,x.QuantityMeaning,x.PriceCurrency);Assert.Equal(2,v.Quantity);Assert.Equal("9007199254740993",v.PriceRial);Assert.Equal("0001-Ab",x.Rows[0].ExternalItemId);Assert.Contains("unit_mapping_required",v.Issues);Assert.Contains("warehouse_mapping_required",v.Issues);Assert.Contains("apply_not_available",v.Issues);}
    [Fact] public void CaseAndLeadingZeroesAreDistinctButDuplicateStableItemsFail(){var x=Input();AccountingImportRules.Validate(x with{Rows=[x.Rows[0],x.Rows[0] with{ExternalItemId="0001-ab"},x.Rows[0] with{ExternalItemId="1-Ab"}]},Now,false);Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(x with{Rows=[x.Rows[0],x.Rows[0]]},Now,false));}
    [Theory][InlineData("-1")][InlineData("1.5")][InlineData("1e2")][InlineData("۱")][InlineData("1,000")][InlineData("1000001")][InlineData("9223372036854775808")]
    public void UnsupportedQuantitiesAreKeptForReviewAndNeverTruncatedToStock(string raw){var x=Input() with{Rows=[Input().Rows[0] with{QuantityRaw=raw}]};AccountingImportRules.Validate(x,Now,false);var v=AccountingImportRules.Inspect(raw,"1","physical","IRR");Assert.Null(v.Quantity);Assert.Contains("quantity_not_supported_integer",v.Issues);Assert.Equal(raw,x.Rows[0].QuantityRaw);}
    [Theory][InlineData("-1")][InlineData("1.5")][InlineData("۱")][InlineData("9223372036854775808")]
    public void InvalidPricesNeverBecomeZeroOrRoundedRial(string raw){var v=AccountingImportRules.Inspect("1",raw,"physical","IRR");Assert.Null(v.PriceRial);Assert.Contains("price_not_supported_integer",v.Issues);}
    [Fact] public void ExplicitTomanConvertsExactlyAndOverflowIsUnusable(){Assert.Equal("90071992547409930",AccountingImportRules.Inspect("1","9007199254740993","physical","IRT").PriceRial);Assert.Null(AccountingImportRules.Inspect("1","922337203685477581","physical","IRT").PriceRial);Assert.Equal(long.MaxValue.ToString(),AccountingImportRules.Inspect("1",long.MaxValue.ToString(),"physical","IRR").PriceRial);}
    [Fact] public void UnknownAndAlreadyAvailableNumbersAreNeverPhysicalStock(){var a=AccountingImportRules.Inspect(null,null,"unknown","unknown");Assert.Null(a.Quantity);Assert.Null(a.PriceRial);Assert.Contains("quantity_meaning_unknown",a.Issues);Assert.Contains("quantity_missing",a.Issues);Assert.Contains("available_quantity_requires_reconciliation",AccountingImportRules.Inspect("1","1","available","IRR").Issues);Assert.Null(AccountingImportRules.Inspect("1","1","physical","unknown").PriceRial);}
    [Fact] public void DemoAndObservationLimitsAreEnforcedBeforeAnyReplay(){var x=Input();Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(x with{IsDemo=true},Now,false));AccountingImportRules.Validate(x with{IsDemo=true},Now,true);Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(x with{ObservedAt=Now.AddTicks(1)},Now,false));Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(x with{ObservedAt=Now.ToOffset(TimeSpan.FromHours(3))},Now,false));}
    [Fact] public void BoundedRowsAndControlCharactersFail(){Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(Input() with{Rows=[]},Now,false));Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(Input() with{Rows=Enumerable.Range(0,201).Select(i=>Input().Rows[0] with{ExternalItemId=i.ToString()}).ToArray()},Now,false));Assert.Throws<BusinessException>(()=>AccountingImportRules.Validate(Input() with{Rows=[Input().Rows[0] with{PriceRaw="1\n2"}]},Now,false));}
    [Fact] public void HashBindsEveryRawValueAndMetadataWithoutNormalizingOpaqueKeys(){var x=Input();Assert.Equal(AccountingImportRules.Hash(x),AccountingImportRules.Hash(x with{}));Assert.NotEqual(AccountingImportRules.Hash(x),AccountingImportRules.Hash(x with{CompanyKey="company-a"}));Assert.NotEqual(AccountingImportRules.Hash(x),AccountingImportRules.Hash(x with{Rows=[x.Rows[0] with{QuantityRaw="02"}]}));Assert.NotEqual(AccountingImportRules.Hash(x),AccountingImportRules.Hash(x with{QuantityMeaning="available"}));}
}
